// ServerName is the server's own name. Every reply the server itself sends starts with ":" + ServerName,
// except the "ERROR :Closing link" line sent when closing a connection.
const ServerName = "freeq-lite"

// MaxLineBytes is the longest accepted line, counting the line's content without its CR/LF terminator.
// A longer line is read to its end and discarded whole: it is never dispatched and never answered.
const MaxLineBytes = 512

// Channel is one live channel. It exists in Server.Channels only while it has at least one member.
type Channel struct {
	// Name is the display name, exactly as given by the JOIN that created the channel.
	Name string
	// Members is the set of clients in the channel.
	Members map[*Client]bool
}

// Client is one TCP connection. Every field is read and written only with Server.mu held,
// except conn and queue, which only the connection's own reader and writer goroutines touch.
type Client struct {
	// Nick is the nick as the user typed it, or "" if no valid NICK has been accepted yet.
	Nick string
	// User is the <user> parameter of USER, or "" if USER has not been accepted yet.
	User string
	// Registered becomes true once both NICK and USER have been accepted. It never goes back to false.
	Registered bool
	// Channels holds the channels this client is in, keyed by strings.ToLower of the channel name.
	Channels map[string]*Channel
	// Closed is set by Server.Disconnect. Once set, Send drops lines and the read loop stops.
	Closed bool
	conn   net.Conn
	queue  chan string
}

// Server holds all shared state. Every field is guarded by mu.
// Keys are always strings.ToLower of the nick or channel name.
type Server struct {
	mu sync.Mutex
	// Clients maps strings.ToLower(nick) to the client holding that nick. It holds every connection
	// that has an accepted nick, registered or not, so nick uniqueness covers both.
	// Handlers that look up a user to talk to must also check Registered.
	Clients map[string]*Client
	// Channels maps strings.ToLower(name) to the live channel.
	Channels map[string]*Channel
}

// Message is one parsed line. Handlers receive Command upper-cased; Params never include the prefix.
type Message struct {
	Command string
	Params  []string
}

// handlers is the command registry, keyed by upper-cased command. Files other than running.go only
// assign into it from init(); only running.go reads it. A handler is always called with s.mu held
// and must never block.
var handlers = map[string]func(s *Server, c *Client, m Message){}
